fn string_xor(a: Vec<char>, b: Vec<char>) -> Vec<char> {
    // Ensure both inputs have the same length
    assert_eq!(a.len(), b.len(), "Inputs must have the same length");

    // Consume both vectors, zip their elements, compute XOR per character,
    // and collect into the result vector.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(c1, c2)| if c1 == c2 { '0' } else { '1' })
     .collect()
}

